pug:
table.row.footer.bg-col(role="presentation" style="background-color:{{ background_color }};border:{{ border }};border-radius:{{ radius }}")
    tr
        td.pb30
            table.twelve.columns(role="presentation")
                tr
                    td
                        .mobile-paddding(style="padding:{{ padding }}")
                            p.warning {{ company_address }}
                            p.warning.pt20 {{ risk_warning }}
                            p.subscribe
                                a.left(href="{{ terms_href }}" universal="true" target="_blank") {{ conditions }}
                                a.right(href="{{ unsubscribe_href }}" universal="true" target="_blank") {{ unsubscribe }}

styl:
.footer{background-color:{{ background_color }};border-collapse:separate!important;border-radius:{{ radius }}!important;padding-bottom:0;padding-top:0}
.mobile-paddding{padding:{{ padding }}}
@media screen and (max-width:600px){.mobile-paddding{padding:30px 20px 0!important}}
.warning{color:{{ text_color }};font-family:Helvetica!important;font-size:14px;letter-spacing:0;line-height:22px;text-align:center}
.subscribe{color:{{ link_color }}!important;font-family:'Roboto','Helvetica','Arial',sans-serif;font-size:14px;font-weight:300;margin:0 auto;padding-top:20px;text-align:left!important;text-decoration:none!important}
a.left{color:{{ link_color }};display:inline-block;font-weight:400;text-align:left;word-break:break-word}
a.right{color:{{ link_color }};display:inline-block;float:right;font-weight:400;text-align:right}
@media screen and (max-width:600px){a.left{display:block!important;padding-bottom:10px!important;text-align:center!important}a.right{display:block!important;float:none!important;text-align:center!important}}
